    const env = _ensurePresetEnv(id);
    if (!env) return;
    scene.background = env;
    scene.environment = env;
    _applyHdriRotation();
    _applyHdriIntensity();
    requestRender();
    const cur = document.getElementById('hdri-current');
    const labels = { outdoor: 'Outdoor', sunset: 'Sunset', overcast: 'Overcast' };
