window.__moResetScene = () => _newSceneHere();
window.__moOpenFile = (file) => _handleSelectedFile(file);
// For the tab strip (any tab's menu may ask about, or copy, this scene).
window.__moHasParts = () => state.parts.some(p => !p.deleted);
window.__moDuplicateScene = async () => {
  const blob = await _withSolidView(() => _saveSceneImpl(true));
  if (!blob) return;
  const base = state.sceneName || state._lastSavedSceneName || (state._loadedFilename || '').replace(/\.[^.]+$/, '') || _Tabs.blankName();
  const file = new File([blob], base + ' copy.glb', { type: 'model/gltf-binary' });
  file.__moNoRecent = true;
  _Tabs.add({ file });
};

// Marks the scene as "active" — fires for both file loads AND `New scene` /
// first primitive add on an empty scene. Unblocks the toolbar (Fit / Save /
// Scene settings work without geometry) and dismisses the welcome splash.
// `onModelLoaded` calls this then layers on the model-specific bits
// (recent-thumb capture, status name).
function onSceneActivated() {
  const _bss = $('btn-save-scene'); if (_bss) _bss.disabled = false;
  // Export still requires geometry — re-evaluated on every part add/remove.
  const _exp = $('btn-export'); if (_exp) _exp.disabled = state.parts.length === 0;
  try { _Welcome?.hide(); } catch (_) {}
  state._sceneActive = true;
}

// When the user last pressed a key or a button, scrolled or dragged. Work that can wait (the picture of a scene for the Recents
// list, a warm spare copy of the app for the next tab) waits for a quiet moment instead of competing with the first seconds of
// use of a model that was just opened, which is when a scene of thousands of parts needs every frame.
let _lastInputAt = performance.now();
for (const ev of ['pointerdown', 'keydown', 'wheel']) window.addEventListener(ev, () => { _lastInputAt = performance.now(); }, { capture: true, passive: true });
