    svCursor   = popEl.querySelector('.cp-sv-cursor');
    hueEl      = popEl.querySelector('.cp-hue');
    hueCursor  = popEl.querySelector('.cp-hue-cursor');
    hexInput   = popEl.querySelector('.cp-hex');
    presetsEl  = popEl.querySelector('.cp-presets');

